import { execFileSync } from 'node:child_process';import{createRequire}from'node:module';import{mkdir,readFile}from'node:fs/promises';import{dirname,join,resolve}from'node:path';import{fileURLToPath}from'node:url';import{build}from'esbuild'
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..'),require=createRequire(join(root,'package.json')),cfg=JSON.parse(await readFile(join(root,'cloudbaserc.json'),'utf8')),cli='D:/app-cache/cloudbase-cli/node_modules/@cloudbase/cli/bin/tcb'
function data(a){const raw=execFileSync(process.execPath,[cli,...a],{cwd:root,encoding:'utf8',windowsHide:true,timeout:30000,maxBuffer:8*1024*1024,stdio:['ignore','pipe','pipe']});const i=raw.indexOf('{');if(i<0)throw Error('CLI_JSON_MISSING');const v=JSON.parse(raw.slice(i));if(v.error)throw Error('CLI_ERROR');return v.data}
const sec=data(['secrets','get','--json']);if(sec?.envId!==cfg.envId||sec?.isTemporary!==true)throw Error('TEMP_TOKEN_INVALID')
const entry=join(root,'.runtime','cip-question-readback','entry.cjs');await mkdir(dirname(entry),{recursive:true});await build({entryPoints:[join(root,'src/seed/m3-public-question-entry.ts')],outfile:entry,bundle:true,format:'cjs',platform:'node',target:'node20',logLevel:'silent'});const api=require(entry),app=require('@cloudbase/js-sdk').init({env:cfg.envId,secretId:sec.secretId,secretKey:sec.secretKey,sessionToken:sec.token}),db=api.createCloudBaseDocumentDatabase(app.database())
const ids=[];for(const code of ['50215','50171'])for(let i=1;i<=10;i++)ids.push(`cip${code}_exercise_${String(i).padStart(2,'0')}_v3`)
const rows=await Promise.all(ids.map(async id=>{const [s,p]=await Promise.all([db.get('learning_resources',id),db.get('learning_resources',api.publicQuestionProjectionId(id,'org_isolation_secondary'))]);return{id,present:!!s,published:s?.status==='published',projected:!!p,projectionPublished:p?.status==='published'}}));console.log(JSON.stringify({count:rows.length,published:rows.filter(x=>x.published&&x.projectionPublished).length,missing:rows.filter(x=>!x.published||!x.projectionPublished).map(x=>x.id),readback:rows}))
